insert into todo.laberinto_nodes (node_id, island_zone, seq, ambient_prompt, doors, feedback_imperfect, next_node_id) values
  ('tf_botanico_01', 'tenerife', 1, 'Ayer por la tarde, mientras yo caminaba por los senderos del jardín...', '[{"text":"...empezaba a llover","correct":false,"tense":"imperfect","feedback":"The rain is a sudden interruption of your walk, not a background state. Interruptions take the indefinido."},{"text":"...empezó a llover","correct":true,"tense":"preterite","feedback":"Mientras + imperfecto sets the stage; the rain bursts in as a completed event: empezó."},{"text":"...empezo a llover","correct":false,"tense":"trap","feedback":"Trap! Without the accent, ''empezo'' is not a Spanish form. The 3rd-person indefinido is ''empezó''."}]'::jsonb, 'The rain is a sudden interruption of your walk, not a background state.', 'tf_botanico_02'),
  ('tf_botanico_02', 'tenerife', 2, 'Leíamos los carteles de los dragos cuando, de repente, un loro...', '[{"text":"...nos robaba el mapa","correct":false,"tense":"imperfect","feedback":"''De repente'' signals a single, sudden action cutting into the reading. Use the indefinido: robó."},{"text":"...nos robe el mapa","correct":false,"tense":"trap","feedback":"Trap! ''Robe'' is present subjunctive. A past narrative event needs ''robó''."},{"text":"...nos robó el mapa","correct":true,"tense":"preterite","feedback":"Background (leíamos) + trigger ''de repente'' = a completed interruption: robó."}]'::jsonb, '''De repente'' signals a single, sudden action cutting into the reading.', 'tf_botanico_03'),
  ('tf_botanico_03', 'tenerife', 3, 'Cuando sonó su teléfono, el jardinero...', '[{"text":"...regó las orquídeas","correct":false,"tense":"preterite","feedback":"The phone rang in the middle of something already happening. That ongoing background action takes the imperfecto: regaba."},{"text":"...regaba las orquídeas","correct":true,"tense":"imperfect","feedback":"The watering was already in progress when the phone interrupted: regaba is the background."},{"text":"...regaría las orquídeas","correct":false,"tense":"trap","feedback":"Trap! ''Regaría'' is conditional (would water). Describe what was going on: regaba."}]'::jsonb, 'The watering was already in progress when the phone interrupted.', 'gc_dunas_01'),
  ('gc_dunas_01', 'gran_canaria', 4, 'El verano pasado, mi hermana y yo...', '[{"text":"...fuimos a Maspalomas por primera vez","correct":true,"tense":"preterite","feedback":"''El verano pasado'' + ''por primera vez'' marks one finished trip. Ir in the indefinido: fuimos."},{"text":"...íbamos a Maspalomas por primera vez","correct":false,"tense":"imperfect","feedback":"A ''first time'' happens once. Iba/íbamos describe repeated or ongoing going, not a single trip."},{"text":"...fueimos a Maspalomas por primera vez","correct":false,"tense":"trap","feedback":"Trap! Ir is fully irregular in the indefinido: fui, fuiste, fue, fuimos, fuisteis, fueron."}]'::jsonb, 'A ''first time'' happens once.', 'gc_dunas_02'),
  ('gc_dunas_02', 'gran_canaria', 5, 'Desde lo alto de la duna, de repente, nosotros...', '[{"text":"...veímos un camello","correct":false,"tense":"trap","feedback":"Trap! Ver drops the accent in the indefinido: vi, viste, vio, vimos, visteis, vieron."},{"text":"...veíamos un camello","correct":false,"tense":"imperfect","feedback":"''De repente'' introduces a sudden, completed perception. Use the indefinido: vimos."},{"text":"...vimos un camello","correct":true,"tense":"preterite","feedback":"A sudden sighting is a single event: vimos. Note: no accent on the short forms of ver."}]'::jsonb, '''De repente'' introduces a sudden, completed perception.', 'gc_dunas_03'),
  ('gc_dunas_03', 'gran_canaria', 6, 'Cuando era niño, mi abuelo...', '[{"text":"...tuvo una barca azul","correct":false,"tense":"preterite","feedback":"Childhood possession is a background description, not an event. Tener in the imperfecto: tenía."},{"text":"...tenió una barca azul","correct":false,"tense":"trap","feedback":"Trap! ''Tenió'' does not exist. Imperfecto: tenía. Indefinido: tuvo."},{"text":"...tenía una barca azul","correct":true,"tense":"imperfect","feedback":"Descriptions of how things were (cuando era niño) take the imperfecto: tenía."}]'::jsonb, 'Descriptions of how things were take the imperfecto.', 'gc_dunas_04'),
  ('gc_dunas_04', 'gran_canaria', 7, 'La excursión a las dunas duró todo el día y...', '[{"text":"...fue inolvidable","correct":true,"tense":"preterite","feedback":"A bounded experience (duró todo el día) judged as a whole takes the indefinido: fue."},{"text":"...fué inolvidable","correct":false,"tense":"trap","feedback":"Trap! Monosyllables like fue, fui, vio, dio never carry an accent."},{"text":"...era inolvidable","correct":false,"tense":"imperfect","feedback":"The trip is finished and summed up as one whole. Ser in the indefinido: fue."}]'::jsonb, 'The trip is finished and summed up as one whole.', 'lz_timanfaya_01'),
  ('lz_timanfaya_01', 'lanzarote', 8, 'Anoche, en la cena, por fin yo...', '[{"text":"...sabía la verdad sobre el volcán","correct":false,"tense":"imperfect","feedback":"''Sabía'' = I already knew (a state). ''Por fin'' means the knowledge arrived at a moment: supe = I found out."},{"text":"...supe la verdad sobre el volcán","correct":true,"tense":"preterite","feedback":"Saber changes meaning in the indefinido: supe = I found out / learned."},{"text":"...sabí la verdad sobre el volcán","correct":false,"tense":"trap","feedback":"Trap! Saber has an irregular stem in the indefinido: supe, supiste, supo..."}]'::jsonb, '''Sabía'' = I already knew. ''Supe'' = I found out.', 'lz_timanfaya_02'),
  ('lz_timanfaya_02', 'lanzarote', 9, 'En 2019, durante mi viaje a Timanfaya, yo...', '[{"text":"...conozí a mi mejor amiga","correct":false,"tense":"trap","feedback":"Trap! Conocer is regular in the indefinido: conocí, conociste, conoció..."},{"text":"...conocí a mi mejor amiga","correct":true,"tense":"preterite","feedback":"Conocer in the indefinido = to meet for the first time: conocí."},{"text":"...conocía a mi mejor amiga","correct":false,"tense":"imperfect","feedback":"''Conocía'' = I already knew her. A first meeting on a specific trip is ''conocí''."}]'::jsonb, '''Conocía'' = I already knew her. A first meeting is ''conocí''.', 'lz_timanfaya_03'),
  ('lz_timanfaya_03', 'lanzarote', 10, 'Intenté abrir la puerta del mirador tres veces, pero...', '[{"text":"...no podía","correct":false,"tense":"imperfect","feedback":"The attempts are finished and counted (tres veces). The outcome is a completed failure: no pude = I tried and failed."},{"text":"...no podí","correct":false,"tense":"trap","feedback":"Trap! Poder has an irregular stem in the indefinido: pude, pudiste, pudo..."},{"text":"...no pude","correct":true,"tense":"preterite","feedback":"No pude = I tried and did not manage. The indefinido of poder reports the result."}]'::jsonb, 'No pude = I tried and failed.', 'lz_timanfaya_04'),
  ('lz_timanfaya_04', 'lanzarote', 11, 'Cuando éramos niños, todos...', '[{"text":"...sabíamos que el suelo de Timanfaya quemaba","correct":true,"tense":"imperfect","feedback":"A known fact during childhood is an ongoing mental state: sabíamos."},{"text":"...supimos que el suelo de Timanfaya quemaba","correct":false,"tense":"preterite","feedback":"''Supimos'' means we found out at one moment. ''Cuando éramos niños'' frames a lasting state: sabíamos."},{"text":"...sabemos que el suelo de Timanfaya quemaba","correct":false,"tense":"trap","feedback":"Trap! ''Sabemos'' is present tense; the frame is in the past."}]'::jsonb, 'A known fact during childhood is an ongoing mental state.', 'fv_viento_01'),
  ('fv_viento_01', 'fuerteventura', 12, 'Todos los veranos, mi familia...', '[{"text":"...alquilaba una casa en Corralejo","correct":true,"tense":"imperfect","feedback":"''Todos los veranos'' = a repeated habit. Habits take the imperfecto: alquilaba."},{"text":"...alquilará una casa en Corralejo","correct":false,"tense":"trap","feedback":"Trap! ''Alquilará'' is future tense."},{"text":"...alquiló una casa en Corralejo","correct":false,"tense":"preterite","feedback":"''Todos los veranos'' describes something that happened again and again, not once. Use alquilaba."}]'::jsonb, '''Todos los veranos'' = a repeated habit.', 'fv_viento_02'),
  ('fv_viento_02', 'fuerteventura', 13, 'Aquel verano, sin embargo, mi familia...', '[{"text":"...alquilaba un barco en Corralejo","correct":false,"tense":"imperfect","feedback":"''Aquel verano, sin embargo'' singles out one summer that broke the routine. One-time events take the indefinido: alquiló."},{"text":"...alquiló un barco en Corralejo","correct":true,"tense":"preterite","feedback":"''Aquel verano'' = one specific time, contrasting with the habit: alquiló."},{"text":"...alquilaste un barco en Corralejo","correct":false,"tense":"trap","feedback":"Trap! ''Alquilaste'' is tú. ''Mi familia'' is third person singular: alquiló."}]'::jsonb, '''Aquel verano'' singles out one summer.', 'fv_viento_03'),
  ('fv_viento_03', 'fuerteventura', 14, 'De pequeña, cada domingo, yo...', '[{"text":"...hice windsurf con mi padre","correct":false,"tense":"preterite","feedback":"''Cada domingo'' marks a routine. Routines in the past take the imperfecto: hacía."},{"text":"...hací windsurf con mi padre","correct":false,"tense":"trap","feedback":"Trap! Hacer in the imperfecto is regular: hacía, hacías, hacía..."},{"text":"...hacía windsurf con mi padre","correct":true,"tense":"imperfect","feedback":"''De pequeña'' + ''cada domingo'' = childhood habit: hacía."}]'::jsonb, '''Cada domingo'' marks a routine.', 'fv_viento_04'),
  ('fv_viento_04', 'fuerteventura', 15, 'El 3 de agosto de 1998, en Sotavento, mi padre...', '[{"text":"...ganó su única regata","correct":true,"tense":"preterite","feedback":"An exact date and ''única'' = one historical event: ganó."},{"text":"...ganaba su única regata","correct":false,"tense":"imperfect","feedback":"A specific date pins a single completed event. Use the indefinido: ganó."},{"text":"...ganío su única regata","correct":false,"tense":"trap","feedback":"Trap! Ganar is a regular -ar verb: gané, ganaste, ganó."}]'::jsonb, 'A specific date pins a single completed event.', 'lp_caldera_01'),
  ('lp_caldera_01', 'la_palma', 16, 'Aquella noche en el Roque de los Muchachos, el cielo...', '[{"text":"...fue claro, aparecía un meteoro y todos gritábamos","correct":false,"tense":"imperfect","feedback":"Flip it: the sky is the setting (imperfecto: era), the meteor and the shout are events in sequence (indefinido: apareció, gritamos)."},{"text":"...era claro, apareció un meteoro y todos gritamos","correct":true,"tense":"preterite","feedback":"Setting (era) → action (apareció) → reaction (gritamos). Background in imperfecto, events in indefinido."},{"text":"...era claro, aparecía un meteoro y todos gritamos","correct":false,"tense":"trap","feedback":"Trap! The meteor is the trigger event, not scenery: apareció."}]'::jsonb, 'Setting in imperfecto, events in indefinido.', 'lp_caldera_02'),
  ('lp_caldera_02', 'la_palma', 17, 'Mientras el astrónomo ajustaba el telescopio...', '[{"text":"...se fue la luz y él soltó una carcajada","correct":true,"tense":"preterite","feedback":"Background (ajustaba) → interruption (se fue) → reaction (soltó). Both events are completed."},{"text":"...se iba la luz y él soltaba una carcajada","correct":false,"tense":"imperfect","feedback":"The blackout and the laugh are single events that happen in order. Use the indefinido: se fue, soltó."},{"text":"...se fue la luz y él soltaba una carcajada","correct":false,"tense":"trap","feedback":"Trap! The reaction is also a one-time event after the blackout: soltó."}]'::jsonb, 'The blackout and the laugh are single events in order.', 'lp_caldera_03'),
  ('lp_caldera_03', 'la_palma', 18, 'Hacía frío en la cumbre y nosotros...', '[{"text":"...esperábamos el amanecer cuando veíamos el mar de nubes","correct":false,"tense":"trap","feedback":"Trap! The ''cuando'' clause is the moment that breaks the waiting: vimos."},{"text":"...esperamos el amanecer cuando veíamos el mar de nubes","correct":false,"tense":"preterite","feedback":"Reversed. The waiting is the ongoing background (esperábamos); seeing the sea of clouds is the event (vimos)."},{"text":"...esperábamos el amanecer cuando vimos el mar de nubes","correct":true,"tense":"imperfect","feedback":"Weather (hacía) + ongoing action (esperábamos) set the scene; ''cuando vimos'' is the event."}]'::jsonb, 'Waiting is the background; seeing is the event.', 'lg_garajonay_01'),
  ('lg_garajonay_01', 'la_gomera', 19, 'Me perdí en Garajonay. Un pastor me encontró, me dio agua y...', '[{"text":"...me llevaba hasta el pueblo","correct":false,"tense":"imperfect","feedback":"The story is a chain of completed actions (encontró, dio...). The next link continues the chain: llevó."},{"text":"...me llevó hasta el pueblo","correct":true,"tense":"preterite","feedback":"A sequence of completed actions moves the plot forward: encontró → dio → llevó."},{"text":"...me llevo hasta el pueblo","correct":false,"tense":"trap","feedback":"Trap! Without the accent, ''llevo'' is present tense (I carry)."}]'::jsonb, 'A chain of completed actions continues in the indefinido.', 'lg_garajonay_02'),
  ('lg_garajonay_02', 'la_gomera', 20, 'Mi abuela creció en una casa de piedra en el bosque. Ella...', '[{"text":"...se levantava antes que el sol","correct":false,"tense":"trap","feedback":"Trap! The -ar imperfecto ending is spelled with b: levantaba."},{"text":"...se levantó antes que el sol","correct":false,"tense":"preterite","feedback":"The story describes her life growing up, not one morning. Routine = imperfecto: se levantaba."},{"text":"...se levantaba antes que el sol","correct":true,"tense":"imperfect","feedback":"No trigger word needed: ''growing up'' frames a way of life, so the routine is imperfecto."}]'::jsonb, 'Describing a way of life = imperfecto.', 'lg_garajonay_03'),
  ('lg_garajonay_03', 'la_gomera', 21, 'Abrí la puerta del refugio. Dentro, el fuego...', '[{"text":"...ardía y olía a laurel","correct":true,"tense":"imperfect","feedback":"After the action (abrí), the narrator describes the scene as found: ardía, olía."},{"text":"...ardió y olió a laurel","correct":false,"tense":"preterite","feedback":"The fire was already burning when you walked in. What you find on arrival is description: ardía, olía."},{"text":"...ardiaba y olía a laurel","correct":false,"tense":"trap","feedback":"Trap! Arder is an -er verb: ardía, not ''ardiaba''."}]'::jsonb, 'The scene you find on arrival is description.', 'eh_faro_01'),
  ('eh_faro_01', 'el_hierro', 22, 'Cuando llegamos al faro de Orchilla, el farero...', '[{"text":"...dormía, así que lo despertamos","correct":true,"tense":"imperfect","feedback":"He was already asleep (background: dormía); waking him is the event (despertamos)."},{"text":"...durmió, así que lo despertábamos","correct":false,"tense":"preterite","feedback":"Swapped: the sleeping is the state you found, the waking is the event."},{"text":"...dormió, así que lo despertamos","correct":false,"tense":"trap","feedback":"Trap! Dormir changes stem in the 3rd person indefinido: durmió."}]'::jsonb, 'The sleeping is background; the waking is the event.', 'eh_faro_02'),
  ('eh_faro_02', 'el_hierro', 23, 'En octubre de 2011, bajo el mar de La Restinga, el volcán...', '[{"text":"...entraba en erupción","correct":false,"tense":"imperfect","feedback":"A dated historical event is a completed action: entró."},{"text":"...entró en erupción","correct":true,"tense":"preterite","feedback":"A specific historical moment = indefinido: entró."},{"text":"...entrió en erupción","correct":false,"tense":"trap","feedback":"Trap! Entrar is regular -ar: entró."}]'::jsonb, 'A dated historical event is a completed action.', 'eh_faro_03'),
  ('eh_faro_03', 'el_hierro', 24, 'Mis primos no vinieron a la fiesta del Garoé porque...', '[{"text":"...estubieron enfermos","correct":false,"tense":"trap","feedback":"Trap! Estar''s indefinido stem is spelled with v: estuvieron."},{"text":"...estaban enfermos","correct":true,"tense":"imperfect","feedback":"The illness is the background reason (a state at that time): estaban."},{"text":"...estuvieron enfermos","correct":false,"tense":"preterite","feedback":"The reason behind an event is usually a background state: estaban enfermos."}]'::jsonb, 'The reason behind an event is a background state.', null)
